"""###Tratamiento de los Datos

####Imputar los valores nulos
"""

#De los variables que poseen nulos, se indentificaron 2
credito['Mto_ingreso_mensual'].fillna(credito['Mto_ingreso_mensual'].mean(),inplace=True)

credito['Nro_dependiente'].fillna(credito['Nro_dependiente'].mean(),inplace=True)

#Validadición de valores NA que se hayan cambiado
credito.isnull().sum()

"""Existen valores de variables que poseen datos atípicos dado la naturaleza de dicha variable. Se identificaron las siguientes:

1. 'Prct_uso_tc',
2. 'Prct_deuda_vs_ingresos'
"""

#Elimino el valor por encima de 1 por el promedio
credito.loc[credito['Prct_uso_tc'] > 1, 'Prct_uso_tc'] = np.nan

credito.loc[credito['Prct_deuda_vs_ingresos'] > 1, 'Prct_deuda_vs_ingresos'] = np.nan

#Revisión de los cambios en las variables topeadas
credito.describe()

#Dado que se eliminó los valores por encima de 1 de las variables 'Prct_uso_tc',
#y 'Prct_deuda_vs_ingresos', se verifican los valores nuloos para reemplazarlos
#por el promedio
credito.isnull().sum()

credito['Prct_deuda_vs_ingresos'].fillna(credito['Prct_deuda_vs_ingresos'].mean(),inplace=True)

credito['Prct_uso_tc'].fillna(credito['Prct_uso_tc'].mean(),inplace=True)

